) -> Self {
    let model = model.into();
    Self {
        id: Uuid::new_v4().to_string(),
        session_id: session_id.into(),
        title: title.into(),
        kind: ArtifactKind::Image,
        summary: format!("{}x{} Image - {}", width, height, model),
        payload: ArtifactPayload::Image {
            prompt: prompt.into(),
            width,
            height,
            file_path,
            preview_url,
            size_bytes,
            model,
        },
        created_at: Utc::now(),
    }
}

    pub fn new_patch(
