    fn pkce_is_secure_url_safe_and_matches_s256() {
        let (verifier, challenge) = OAuthHandler::generate_pkce().unwrap();
        assert!((43..=128).contains(&verifier.len()));
        assert!(verifier
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-' || byte == b'_'));
        assert_eq!(
