use async_trait::async_trait;
use eventsource_stream::Eventsource;
use futures_util::StreamExt;
use odon_core::{MessageRole, OdonError, Result};
use reqwest::header::{HeaderMap, HeaderValue, AUTHORIZATION, CONTENT_TYPE};
use serde_json::json;
use tokio::sync::mpsc::Sender;
use tokio_util::sync::CancellationToken;

use crate::stream::StreamEvent;
use crate::trait_def::{ChatRequest, ModelProvider};

pub struct OpenAiCompatibleProvider {
    client: reqwest::Client,
    base_url: String,
    api_key: String,
    provider_label: String,
}

impl OpenAiCompatibleProvider {
    pub fn new(
        base_url: impl Into<String>,
        api_key: impl Into<String>,
        label: Option<&str>,
    ) -> Self {
        Self {
            client: reqwest::Client::new(),
            base_url: base_url.into(),
            api_key: api_key.into(),
            provider_label: label.unwrap_or("openai-compatible").to_string(),
        }
    }

    pub fn new_deepseek(api_key: impl Into<String>) -> Self {
        Self::new("https://api.deepseek.com/v1", api_key, Some("deepseek"))
    }

    pub fn new_qwen(api_key: impl Into<String>) -> Self {
        Self::new("https://dashscope-intl.aliyuncs.com/compatible-mode/v1", api_key, Some("qwen"))
    }

    pub fn new_alibaba(api_key: impl Into<String>) -> Self {
        Self::new("https://dashscope.aliyuncs.com/compatible-mode/v1", api_key, Some("alibaba"))
    }

    pub fn new_stepfun(api_key: impl Into<String>) -> Self {
        Self::new("https://api.stepfun.com/v1", api_key, Some("stepfun"))
    }
}

#[async_trait]
impl ModelProvider for OpenAiCompatibleProvider {
    fn provider_name(&self) -> &str {
        &self.provider_label
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
        event_sender: Sender<StreamEvent>,
        cancellation: CancellationToken,
    ) -> Result<()> {
        let endpoint = format!("{}/chat/completions", self.base_url.trim_end_matches('/'));

        let mut headers = HeaderMap::new();
        headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        if !self.api_key.is_empty() {
            let auth_val = format!("Bearer {}", self.api_key);
            if let Ok(val) = HeaderValue::from_str(&auth_val) {
                headers.insert(AUTHORIZATION, val);
            }
        }

// Format messages
let mut messages_payload = Vec::new();
if let Some(sys) = request.system_prompt {
    messages_payload.push(json!({
        "role": "system",
        "content": sys,
    }));
}

for msg in request.messages {
    match msg.role {
        MessageRole::User => {
            messages_payload.push(json!({
                "role": "user",
                "content": msg.content.text,
            }));
        }
        MessageRole::System => {
            messages_payload.push(json!({
                "role": "system",
                "content": msg.content.text,
            }));
        }
        MessageRole::Assistant => {
            let mut obj = json!({
                "role": "assistant",
                "content": if msg.content.text.is_empty() { serde_json::Value::Null } else { json!(msg.content.text) },
            });
            if !msg.content.tool_calls.is_empty() {
                let tcs: Vec<_> = msg.content.tool_calls.iter().map(|tc| {
                    json!({
                        "id": tc.call_id,
                        "type": "function",
                        "function": {
                            "name": tc.tool_name,
                            "arguments": tc.arguments.to_string(),
                        }
                    })
                }).collect();
                obj["tool_calls"] = json!(tcs);
            }
            messages_payload.push(obj);
        }
        MessageRole::Tool => {
            messages_payload.push(json!({
                "role": "tool",
                "tool_call_id": msg.id,
                "content": msg.content.text,
            }));
        }
    }
}

let mut body = json!({
    "model": request.model,
    "messages": messages_payload,
    "stream": true,
});

if !request.tools.is_empty() {
    let tools_json: Vec<_> = request
        .tools
        .into_iter()
        .map(|t| {
            json!({
                "type": "function",
                "function": {
                    "name": t.name,
                    "description": t.description,
                    "parameters": t.parameters,
                }
            })
        })
        .collect();
    body["tools"] = json!(tools_json);
}

let resp = self
    .client
    .post(&endpoint)
    .headers(headers)
    .json(&body)
    .send()
    .await
    .map_err(|e| OdonError::Provider {
        provider: self.provider_label.clone(),
        message: format!("HTTP request failed: {}", e),
    })?;

if !resp.status().is_success() {
    let err_body = resp.text().await.unwrap_or_default();
    return Err(OdonError::Provider {
        provider: self.provider_label.clone(),
        message: format!("HTTP status error: {}", err_body),
    });
}

let mut stream = resp.bytes_stream().eventsource();

loop {
    tokio::select! {
        _ = cancellation.cancelled() => {
            let _ = event_sender.send(StreamEvent::Done).await;
            return Ok(());
        }
        item = stream.next() => {
            match item {
                Some(Ok(event)) => {
                    if event.data == "[DONE]" {
                        let _ = event_sender.send(StreamEvent::Done).await;
                        break;
                    }
                    if let Ok(val) = serde_json::from_str::<serde_json::Value>(&event.data) {
                        if let Some(choices) = val.get("choices").and_then(|c| c.as_array()) {
                            if let Some(first) = choices.first() {
                                let delta = first.get("delta");
                                if let Some(content) = delta.and_then(|d| d.get("content")).and_then(|c| c.as_str()) {
                                    let _ = event_sender.send(StreamEvent::TextDelta(content.to_string())).await;
                                }
                                if let Some(thought) = delta.and_then(|d| d.get("reasoning_content")).and_then(|c| c.as_str()) {
                                    let _ = event_sender.send(StreamEvent::ThoughtDelta(thought.to_string())).await;
                                }
                                if let Some(tool_calls) = delta.and_then(|d| d.get("tool_calls")).and_then(|t| t.as_array()) {
                                    for tc in tool_calls {
                                        let idx = tc.get("index").and_then(|i| i.as_u64()).unwrap_or(0) as usize;
                                        let id = tc.get("id").and_then(|s| s.as_str()).map(|s| s.to_string());
                                        let func = tc.get("function");
                                        let name = func.and_then(|f| f.get("name")).and_then(|n| n.as_str()).map(|s| s.to_string());
                                        let args = func.and_then(|f| f.get("arguments")).and_then(|a| a.as_str()).map(|s| s.to_string());

                                        let _ = event_sender.send(StreamEvent::ToolCallDelta {
                                            index: idx,
                                            id,
                                            name,
                                            arguments_delta: args,
                                        }).await;
                                    }
                                }
                            }
                        }
                    }
                }
                Some(Err(e)) => {
                    let _ = event_sender.send(StreamEvent::Error(format!("SSE error: {}", e))).await;
                    break;
                }
                None => {
                    let _ = event_sender.send(StreamEvent::Done).await;
                    break;
                }
            }
        }
    }
}

use async_trait::async_trait;
use odon_core::{MessageRole, Result};
use tokio::sync::mpsc::Sender;
use tokio_util::sync::CancellationToken;

use crate::stream::StreamEvent;
use crate::trait_def::{ChatRequest, ModelProvider};

pub struct SimulatedProvider {
    name: String,
}

impl Default for SimulatedProvider {
    fn default() -> Self {
        Self::new("odon-simulated")
    }
}

impl SimulatedProvider {
    pub fn new(name: impl Into<String>) -> Self {
        Self { name: name.into() }
    }
}

#[async_trait]
impl ModelProvider for SimulatedProvider {
    fn provider_name(&self) -> &str {
        &self.name
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
        event_sender: Sender<StreamEvent>,
        cancellation: CancellationToken,
    ) -> Result<()> {
        let last_user_msg = request
            .messages
            .iter()
            .rev()
            .find(|m| m.role == MessageRole::User)
            .map(|m| m.content.text.to_lowercase())
            .unwrap_or_default();

        let has_tool_results = request.messages.iter().any(|m| m.role == MessageRole::Tool);

        // Simulate short thinking delay
        let _ = event_sender
            .send(StreamEvent::ThoughtDelta(
                "Analyzing user intent, evaluating tools and synthesizing response...".to_string(),
            ))
            .await;
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;

        if cancellation.is_cancelled() {
            let _ = event_sender.send(StreamEvent::Done).await;
            return Ok(());
        }

        // If the user asked to inspect files, system, or run tools and we haven't executed a tool yet:
        if !has_tool_results && (last_user_msg.contains("system") || last_user_msg.contains("sistem") || last_user_msg.contains("environment") || last_user_msg.contains("info")) {
            let call_id = format!("call_sys_info_{}", uuid::Uuid::new_v4().simple());
            let _ = event_sender.send(StreamEvent::ToolCallDelta {
                index: 0,
                id: Some(call_id),
                name: Some("system_info".to_string()),
                arguments_delta: Some("{}".to_string()),
            }).await;
            let _ = event_sender.send(StreamEvent::Done).await;
            return Ok(());
        }

        if !has_tool_results && (last_user_msg.contains("list file") || last_user_msg.contains("dir") || last_user_msg.contains("check files") || last_user_msg.contains("berkas") || last_user_msg.contains("daftar file")) {
            let call_id = format!("call_fs_list_{}", uuid::Uuid::new_v4().simple());
            let _ = event_sender.send(StreamEvent::ToolCallDelta {
                index: 0,
                id: Some(call_id),
                name: Some("fs_list".to_string()),
                arguments_delta: Some(r#"{"path":"."}"#.to_string()),
            }).await;
            let _ = event_sender.send(StreamEvent::Done).await;
            return Ok(());
        }

        let latest_tool_output = request
            .messages
            .iter()
            .rev()
            .find(|m| m.role == MessageRole::Tool)
            .map(|m| m.content.text.clone());

        // If the user requested code, app, or personal knowledge hub:
        let generated_text;
        let response_text = if last_user_msg.contains("knowledge hub") || last_user_msg.contains("build") || last_user_msg.contains("react") {
            "I'm on it! I will build the **Personal Knowledge Hub** project end-to-end.\n\n\
            Here is what has been assembled for your workspace:\n\n\
            1. **Core Application**: A lightweight, responsive React 19 note-taking app with tagging, full-text search, and local persistence.\n\
            2. **Product Requirement Document (PRD)**: Comprehensive specification covering goals, persona workflows, API contracts, and non-functional requirements.\n\
            3. **Visual Mockups**: High-resolution interface preview and hero branding cards.\n\n\
            You can preview, modify, or download the generated artifacts in the Artifacts panel to the right."
        } else if let Some(tool_output) = latest_tool_output {
            generated_text = format!(
                "Berikut hasil eksekusi alat dan telemetri lingkungan kerja Anda:\n\n```json\n{}\n```\n\nEksekusi alat berhasil diselesaikan dan dicatat ke dalam database SQLite sesi aktif.",
                tool_output
            );
            &generated_text
        } else if last_user_msg.contains("search") || last_user_msg.contains("cari") {
            "Here are the findings based on your inquiry. The parameters have been checked against the active workspace knowledge base and online documentation. Let me know if you would like me to drill down further or write a tailored script."
        } else {
            "Hello! I am **ODON (Open Digital Orchestration Network)**, your autonomous AI desktop assistant.\n\n\
            I can help you:\n\
            - **Code & Build**: Generate fullstack web apps, scripts, or debug existing codebases.\n\
            - **Research & Write**: Produce PRDs, architecture specifications, and technical reports.\n\
            - **Automate**: Run background shell operations, git workflows, and connect to relays (CLI, Telegram, WhatsApp).\n\n\
            What would you like to work on today?"
        };

        // Stream response in small words
        for chunk in response_text.split_inclusive(' ') {
            if cancellation.is_cancelled() {
                break;
            }
            let _ = event_sender.send(StreamEvent::TextDelta(chunk.to_string())).await;
            tokio::time::sleep(std::time::Duration::from_millis(15)).await;
        }

        let _ = event_sender.send(StreamEvent::Done).await;
        Ok(())
    }
}

